    conduit::VoidResult encode(conduit::io::BitWriter& w) const {
        int last_octet = 0;
        if (i010_.has_value() && 0 > last_octet) last_octet = 0;
        if (i025_.has_value() && 0 > last_octet) last_octet = 0;
        if (i410_.has_value() && 0 > last_octet) last_octet = 0;
        if (i140_.has_value() && 0 > last_octet) last_octet = 0;
        if (i400_.has_value() && 0 > last_octet) last_octet = 0;
        if (i040_.has_value() && 0 > last_octet) last_octet = 0;
        if (i220_.has_value() && 0 > last_octet) last_octet = 0;
        if (i161_.has_value() && 1 > last_octet) last_octet = 1;
        if (i042_.has_value() && 1 > last_octet) last_octet = 1;
        if (i200_.has_value() && 1 > last_octet) last_octet = 1;
        if (i415_.has_value() && 1 > last_octet) last_octet = 1;
        if (i420_.has_value() && 1 > last_octet) last_octet = 1;
        if (i440_.has_value() && 1 > last_octet) last_octet = 1;
        if (spf_.has_value() && 2 > last_octet) last_octet = 2;
        if (ref_.has_value() && 2 > last_octet) last_octet = 2;
        std::array<uint8_t, 3> fspec{};
        if (i010_.has_value()) fspec[0] |= (1 << 7);
        if (i025_.has_value()) fspec[0] |= (1 << 6);
        if (i410_.has_value()) fspec[0] |= (1 << 5);
        if (i140_.has_value()) fspec[0] |= (1 << 4);
        if (i400_.has_value()) fspec[0] |= (1 << 3);
        if (i040_.has_value()) fspec[0] |= (1 << 2);
        if (i220_.has_value()) fspec[0] |= (1 << 1);
        if (i161_.has_value()) fspec[1] |= (1 << 7);
        if (i042_.has_value()) fspec[1] |= (1 << 6);
        if (i200_.has_value()) fspec[1] |= (1 << 5);
        if (i415_.has_value()) fspec[1] |= (1 << 4);
        if (i420_.has_value()) fspec[1] |= (1 << 3);
        if (i440_.has_value()) fspec[1] |= (1 << 2);
        if (spf_.has_value()) fspec[2] |= (1 << 2);
        if (ref_.has_value()) fspec[2] |= (1 << 1);
        for (size_t i = 0; i < static_cast<size_t>(last_octet); i++) fspec[i] |= (1 << 0);
        w.write_bytes(std::span<const uint8_t>(fspec.data(), static_cast<size_t>(last_octet) + 1));
        if (i010_.has_value()) {
            CONDUIT_TRY(i010_->encode(w));
        }
        if (i025_.has_value()) {
            CONDUIT_TRY(i025_->encode(w));
        }
        if (i410_.has_value()) {
            CONDUIT_TRY(i410_->encode(w));
        }
        if (i140_.has_value()) {
            CONDUIT_TRY(i140_->encode(w));
        }
        if (i400_.has_value()) {
            CONDUIT_TRY(i400_->encode(w));
        }
        if (i040_.has_value()) {
            CONDUIT_TRY(i040_->encode(w));
        }
        if (i220_.has_value()) {
            w.write_bits(*i220_, 24);
        }
        if (i161_.has_value()) {
            CONDUIT_TRY(i161_->encode(w));
        }
        if (i042_.has_value()) {
            CONDUIT_TRY(i042_->encode(w));
        }
        if (i200_.has_value()) {
            CONDUIT_TRY(i200_->encode(w));
        }
        if (i415_.has_value()) {
            CONDUIT_TRY(i415_->encode(w));
        }
        if (i420_.has_value()) {
            CONDUIT_TRY(i420_->encode(w));
        }
        if (i440_.has_value()) {
            CONDUIT_TRY(i440_->encode(w));
        }
        if (spf_.has_value()) {
            CONDUIT_TRY(spf_->encode(w));
        }
        if (ref_.has_value()) {
            CONDUIT_TRY(ref_->encode(w));
        }
        if (w.has_error()) return std::unexpected(w.error());
        return {};
    }

    static conduit::Result<Cat007UplinkRecord_items> decode(conduit::io::BitReader& r) {
        Cat007UplinkRecord_items result;

        // Read FSPEC bitmap
        std::array<uint8_t, 3> fspec{};
        size_t fspec_len = 0;
        while (true) {
            auto byte = r.read_u8();
            if (!byte) return std::unexpected(byte.error());
            if (fspec_len < 3) fspec[fspec_len] = *byte;
            fspec_len++;
            if (!(*byte & (1 << 0))) break;
        }

        if (fspec_len > 0 && (fspec[0] & (1 << 7))) {
            auto val = DataSourceId::decode(r);
            if (!val) return std::unexpected(val.error());
            result.i010_ = std::move(*val);
        }
        if (fspec_len > 0 && (fspec[0] & (1 << 6))) {
            auto val = DataSourceId::decode(r);
            if (!val) return std::unexpected(val.error());
            result.i025_ = std::move(*val);
        }
        if (fspec_len > 0 && (fspec[0] & (1 << 5))) {
            auto val = Cat007I410::decode(r);
            if (!val) return std::unexpected(val.error());
            result.i410_ = std::move(*val);
        }
        if (fspec_len > 0 && (fspec[0] & (1 << 4))) {
            auto val = time_of_day::decode(r);
            if (!val) return std::unexpected(val.error());
            result.i140_ = std::move(*val);
        }
        if (fspec_len > 0 && (fspec[0] & (1 << 3))) {
            auto val = Cat007I400::decode(r);
            if (!val) return std::unexpected(val.error());
            result.i400_ = std::move(*val);
        }
        if (fspec_len > 0 && (fspec[0] & (1 << 2))) {
            auto val = Cat007I040::decode(r);
            if (!val) return std::unexpected(val.error());
            result.i040_ = std::move(*val);
        }
        if (fspec_len > 0 && (fspec[0] & (1 << 1))) {
            auto val = r.read_bits(24);
            if (!val) return std::unexpected(val.error());
            result.i220_ = static_cast<aircraft_address>(*val);
        }
        if (fspec_len > 1 && (fspec[1] & (1 << 7))) {
            auto val = Cat007I161::decode(r);
            if (!val) return std::unexpected(val.error());
            result.i161_ = std::move(*val);
        }
        if (fspec_len > 1 && (fspec[1] & (1 << 6))) {
            auto val = Cat007I042::decode(r);
            if (!val) return std::unexpected(val.error());
            result.i042_ = std::move(*val);
        }
        if (fspec_len > 1 && (fspec[1] & (1 << 5))) {
            auto val = Cat007I200::decode(r);
            if (!val) return std::unexpected(val.error());
            result.i200_ = std::move(*val);
        }
        if (fspec_len > 1 && (fspec[1] & (1 << 4))) {
            auto val = Cat007I415::decode(r);
            if (!val) return std::unexpected(val.error());
            result.i415_ = std::move(*val);
        }
        if (fspec_len > 1 && (fspec[1] & (1 << 3))) {
            auto val = Cat007I420::decode(r);
            if (!val) return std::unexpected(val.error());
            result.i420_ = std::move(*val);
        }
        if (fspec_len > 1 && (fspec[1] & (1 << 2))) {
            auto val = Cat007I440::decode(r);
            if (!val) return std::unexpected(val.error());
            result.i440_ = std::move(*val);
        }
        if (fspec_len > 2 && (fspec[2] & (1 << 2))) {
            auto val = Cat007UplinkRecord_items_spf::decode(r);
            if (!val) return std::unexpected(val.error());
            result.spf_ = std::move(*val);
        }
        if (fspec_len > 2 && (fspec[2] & (1 << 1))) {
            auto val = Cat007UplinkRecord_items_ref::decode(r);
            if (!val) return std::unexpected(val.error());
            result.ref_ = std::move(*val);
        }

        return result;
    }

