// CAT007 Uplink Record (Uplink UAP, Table 3)
// Applies to message types 5-8 as defined in I007/410:
// 5 = Interrogation Request Type A, 6 = Interrogation Request Type B,
// 7 = Interrogation Request Type C, 8 = Selective BDS-Register Request
class Cat007UplinkRecord {
public:
    static constexpr uint64_t TYPE_ID = 0x8d0fb175aeb7de98ULL;
    static constexpr std::string_view TYPE_NAME = "Cat007UplinkRecord";
    static constexpr uint8 ID_VALUE = 7;

    uint8 cat() const { return cat_; }
    [[deprecated("auto-managed: value is set automatically during frame encoding")]]
    void set_cat(uint8 v) { cat_ = v; }
    uint16 len() const { return len_; }
    [[deprecated("auto-managed: value is set automatically during frame encoding")]]
    void set_len(uint16 v) { len_ = v; }

    const Cat007UplinkRecord_items& items() const { return items_; }
    Cat007UplinkRecord_items& mutable_items() { return items_; }
    void set_items(const Cat007UplinkRecord_items& v) { items_ = v; }

    bool operator==(const Cat007UplinkRecord&) const = default;

    conduit::VoidResult encode(conduit::io::BitWriter& w) const {
        CONDUIT_TRY(items_.encode(w));
        if (w.has_error()) return std::unexpected(w.error());
        return {};
    }

    static conduit::Result<Cat007UplinkRecord> decode(conduit::io::BitReader& r) {
        Cat007UplinkRecord result;
        {
            auto val = Cat007UplinkRecord_items::decode(r);
            if (!val) return std::unexpected(val.error());
            result.items_ = std::move(*val);
        }
        return result;
    }

    std::string to_string(std::span<const std::pair<std::string, std::string>> overrides) const {
        auto ov = [&](std::string_view n) -> const std::string* {
            for (const auto& [k, v] : overrides) if (k == n) return &v;
            return nullptr;
        };
        std::ostringstream oss;
        oss << "Cat007UplinkRecord{"
            << "cat="
            ;
            if (auto* ov_val = ov("cat")) oss << *ov_val;
            else oss << +(cat_);
            oss
            << ", len="
            ;
            if (auto* ov_val = ov("len")) oss << *ov_val;
            else oss << +(len_);
            oss
            << ", items=" << items_.to_string()
            << "}";
        return oss.str();
    }
    std::string to_string() const { return to_string({}); }

private:
    friend class AsterixDataBlock;

    uint8 cat_{};
    uint16 len_{};
    Cat007UplinkRecord_items items_{};
public:
    conduit::Result<std::vector<uint8_t>> encode_bytes() const {
        conduit::io::BitWriter w;
        CONDUIT_TRY(encode(w));
        return w.finish();
    }

    static conduit::Result<Cat007UplinkRecord> decode_bytes(std::span<const uint8_t> data, size_t max_bytes = 0) {
        if (max_bytes > 0 && data.size() > max_bytes) {
            return std::unexpected(conduit::Error(conduit::ErrorCode::MaxLengthExceeded,
                "message size " + std::to_string(data.size()) + " exceeds limit " + std::to_string(max_bytes)));
        }
        conduit::io::BitReader r(data);
        return decode(r);
    }
};

